import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Sprite dimensions: 512:320 aspect ratio
  const spriteHeight = 1.0;
  const spriteWidth = (512 / 320) * spriteHeight;

  // Geometry for billboard sprite
  const geometry = new THREE.PlaneGeometry(spriteWidth, spriteHeight);

  // Load and configure texture
  const textureUrl = config.imageUrl || '/prism-mock/home/nodes/floating-accent.png';
  const textureMap = ctx.textureLoader.load(textureUrl);
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Material for sprite
  const material = new THREE.MeshBasicNodeMaterial({
    map: textureMap,
    transparent: true,
    side: THREE.FrontSide,
  });

  // Sprite mesh
  const sprite = new THREE.Mesh(geometry, material);
  group.add(sprite);

  // Add text overlay
  if (config.textContent?.[0] && ctx.fontAtlas) {
    const textContent = config.textContent[0];
    const textStr = typeof textContent === 'string' ? textContent : textContent.text;

    const textMesh = ctx.fontAtlas.createText(textStr, {
      fontSize: 0.34,
      fontFamily: 'Lora',
      fontWeight: 400,
      color: new THREE.Color(0x16161d),
      align: 'center',
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      textMesh.position.y = 0.1;
      group.add(textMesh);
    }
  }

  // Apply scene transforms
  const pos = config.scenePosition;
  if (pos) {
    group.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);
    if (pos.rotationXYZ) {
      group.rotation.set(pos.rotationXYZ[0], pos.rotationXYZ[1], pos.rotationXYZ[2]);
    }
    if (pos.scaleXYZ) {
      group.scale.set(pos.scaleXYZ[0], pos.scaleXYZ[1], pos.scaleXYZ[2]);
    }
  }

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives) && ctx.primitives) {
    for (const prim of config.cinematicPrimitives) {
      ctx.primitives[prim.name]?.(group, prim.params || {});
    }
  }

  // Event handlers
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
    gsap.killTweensOf(group);
  };

  return group;
}
